import React, { useState, useEffect } from 'react';

function App() {
    const [status, setStatus] = useState('در حال اتصال...');
    const [error, setError] = useState('');

    useEffect(() => {
        fetch('http://localhost:8000/api/anomalies/')
            .then(response => {
                if (response.ok) {
                    setStatus('✅ بک‌اند در دسترس است!');
                } else {
                    setStatus('⚠️ بک‌اند پاسخ داد اما خطایی دارد');
                }
            })
            .catch(err => {
                setStatus('❌ بک‌اند در دسترس نیست!');
                setError(err.message);
            });
    }, []);

    return (
        <div style={{ textAlign: 'center', marginTop: '100px', fontFamily: 'Segoe UI' }}>
            <h1 style={{ color: '#1976d2' }}>🚀 سیستم مدیریت ایمنی</h1>
            <div style={{
                marginTop: '30px',
                padding: '20px',
                backgroundColor: status.includes('✅') ? '#d4edda' : '#f8d7da',
                borderRadius: '8px',
                maxWidth: '500px',
                marginLeft: 'auto',
                marginRight: 'auto'
            }}>
                <h3>{status}</h3>
                {error && <p style={{ color: 'red' }}>{error}</p>}
            </div>
            <div style={{ marginTop: '40px' }}>
                <p>📋 پنل ادمین: <a href="http://localhost:8000/admin">http://localhost:8000/admin</a></p>
                <p>🔑 کاربر: admin / رمز: 123456</p>
            </div>
        </div>
    );
}

export default App;
